class SmoothWeightedRR {
  constructor(servers) {
    this.servers = servers.map(s => ({ ...s, current: 0 }));
    this.total = servers.reduce((sum, s) => sum + s.weight, 0);
  }
  pick() {
    let best = null;
    for (const s of this.servers) {
      s.current += s.weight;
      if (!best || s.current > best.current) best = s;
    }
    best.current -= this.total;
    return best.name;
  }
}
const lb = new SmoothWeightedRR([
  { name: 'A', weight: 5 }, { name: 'B', weight: 1 }, { name: 'C', weight: 1 },
]);
console.log(Array.from({ length: 7 }, () => lb.pick()).join(''));
// AABACAA -> 5 A's, 1 B, 1 C, nicely interleaved
